from importlib.machinery import SourceFileLoader
v=SourceFileLoader('v','evidence/browser-validation.py').load_module()
v.ab('reload');v.pause();v.click('Duplicate');d=v.state();assert d['sources'][-1]['x']!=d['sources'][0]['x'];v.report('FIXED duplicate offset',d['sources']);v.fieldvisible();v.shot('duplicate-fixed.png')
v.select('Experiment preset','array');v.pause();v.ab('focus','#phase');v.ab('press','Home');v.ab('press','ArrowRight');before=v.state()['sources'];v.ab('find','text','Your workspace','click');v.click('Save locally');v.click('Restore');after=v.state()['sources'];assert [s['phase'] for s in before]==[s['phase'] for s in after];v.report('FIXED restored custom phases preserved',after);v.shot('array-phase-fixed.png')
v.select('Experiment preset','interference');v.pause();v.ab('find','text','Simulation settings','click');v.fill('Timestep (s)','.001');v.ab('press','Tab');v.select('Substeps / frame','12');v.resume();v.waitsim(7);v.pause();d=v.state();assert all(p['samples']>4900 and p['frequency'] is not None for p in d['probes']);v.report('FIXED five-second probe retention at tiny dt',d['probes']);v.fieldvisible();v.shot('probe-history-fixed.png')
